    def __init__(self):
        self.text = ''
        self.cursor = 0

    def add_text(self, text):
        self.text = self.text[:self.cursor] + text + self.text[self.cursor:]   # O(n) string rebuild
        self.cursor += len(text)

    def delete_prev_chars(self, k):
        actual = min(k, self.cursor)
        self.text = self.text[:self.cursor - actual] + self.text[self.cursor:]  # O(n) string rebuild
        self.cursor -= actual
        return actual

    def cursor_left(self, k):
        self.cursor = max(0, self.cursor - k)
        return self.text[max(0, self.cursor - 10):self.cursor]

    def cursor_right(self, k):
        self.cursor = min(len(self.text), self.cursor + k)
        return self.text[max(0, self.cursor - 10):self.cursor]

