class TextEditor:
    def __init__(self):
        self.left = []          # characters before the cursor, top = closest to cursor
        self.right = []         # characters after the cursor, top = closest to cursor

    def add_text(self, text):
        for c in text:
            self.left.append(c)                    # push onto left, O(1) per char

    def delete_prev_chars(self, k):
        count = 0
        while k > 0 and self.left:
            self.left.pop()                          # pop from left, O(1) per char
            k -= 1
            count += 1
        return count

    def cursor_left(self, k):
        while k > 0 and self.left:
            self.right.append(self.left.pop())        # move left -> right
            k -= 1
        return ''.join(self.left[-10:])

    def cursor_right(self, k):
        while k > 0 and self.right:
            self.left.append(self.right.pop())         # move right -> left
            k -= 1
        return ''.join(self.left[-10:])

