import java.util.*;

class TextEditor {
    Deque<Character> left = new ArrayDeque<>();     // characters before the cursor
    Deque<Character> right = new ArrayDeque<>();    // characters after the cursor

    void addText(String text) {
        for (char c : text.toCharArray()) left.push(c);      // push onto left, O(1) per char
    }

    int deletePrevChars(int k) {
        int count = 0;
        while (k-- > 0 && !left.isEmpty()) { left.pop(); count++; }  // pop from left
        return count;
    }

    String cursorLeft(int k) {
        while (k-- > 0 && !left.isEmpty()) right.push(left.pop());    // move left -> right
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = left.iterator();
        List<Character> buf = new ArrayList<>();
        while (it.hasNext() && buf.size() < 10) buf.add(it.next());
        for (int i = buf.size() - 1; i >= 0; i--) sb.append(buf.get(i));
        return sb.toString();
    }

    String cursorRight(int k) {
        while (k-- > 0 && !right.isEmpty()) left.push(right.pop());     // move right -> left
        StringBuilder sb = new StringBuilder();
        Iterator<Character> it = left.iterator();
        List<Character> buf = new ArrayList<>();
        while (it.hasNext() && buf.size() < 10) buf.add(it.next());
        for (int i = buf.size() - 1; i >= 0; i--) sb.append(buf.get(i));
        return sb.toString();
    }
}

