#include <bits/stdc++.h>
using namespace std;

class TextEditor {
public:
    vector<char> left, right;             // left: before cursor, right: after cursor

    void addText(string text) {
        for (char c : text) left.push_back(c);              // push onto left, O(1) per char
    }

    int deletePrevChars(int k) {
        int count = 0;
        while (k-- > 0 && !left.empty()) { left.pop_back(); count++; }  // pop from left
        return count;
    }

    string cursorLeft(int k) {
        while (k-- > 0 && !left.empty()) { right.push_back(left.back()); left.pop_back(); }  // move left -> right
        int start = max(0, (int)left.size() - 10);
        return string(left.begin() + start, left.end());
    }

    string cursorRight(int k) {
        while (k-- > 0 && !right.empty()) { left.push_back(right.back()); right.pop_back(); }  // move right -> left
        int start = max(0, (int)left.size() - 10);
        return string(left.begin() + start, left.end());
    }
};
